// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t0, uint256 delay, address actor) public {
        t0 = bound(t0, 1, 2 ** 60);
        delay = bound(delay, 0, 2 ** 40);
        vm.assume(actor != address(0) && actor != address(c));

        vm.warp(t0);
        vm.roll(block.number + 1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        bool ok1;
        try c.fallback{value: 10 ether}() { ok1 = true; } catch { ok1 = false; }

        if (ok1) {
            // General rule: a successful call at timestamp t must set
            // pastBlockTime strictly greater than t, i.e. t + 1.
            assertTrue(c.pastBlockTime() == t0 + 1);
        } else {
            // even the first call must obey: if it succeeded at t0 with
            // pastBlockTime previously 0, rule trivially checked above.
            assertTrue(true);
        }

        uint256 t1 = t0 + delay;
        vm.warp(t1);
        vm.roll(block.number + 1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        bool ok2;
        try c.fallback{value: 10 ether}() { ok2 = true; } catch { ok2 = false; }

        if (ok2) {
            assertTrue(c.pastBlockTime() == t1 + 1);
        }
    }
}

