pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint64 warpTime, uint256 blockNumber) public {
        uint256 t = 1000000000 + (warpTime % 1e9);
        vm.assume(t > 1);
        vm.warp(t);
        vm.roll(bound(blockNumber, 1, 10_000_000));

        address actor = address(0xABCD);
        vm.deal(actor, 10 ether);

        bool ok;
        vm.prank(actor);
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after any admissible call (10 ether, strictly increasing time),
        // the contract records pastBlockTime = current timestamp + 1, exactly.
        assertTrue(
            !ok || (c.pastBlockTime() == block.timestamp + 1),
            "pastBlockTime must equal call timestamp + 1"
        );
    }
}

