pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, uint256 delta) public {
        // Wide admissible domain: t1 is a plausible timestamp, delta in [0, 10]
        t1 = bound(t1, 1, 1e18);
        delta = bound(delta, 0, 10);

        // First call at time t1 succeeds in both P and M (P: t1 > 0 = pastBlockTime)
        vm.warp(t1);
        vm.deal(address(this), 10 ether);
        c.fallback{value: 10 ether}();
        uint256 stored1 = c.pastBlockTime();

        // Invariant: a successful call always stores block.timestamp + 1
        assertTrue(stored1 == t1 + 1, "first call must store timestamp+1");

        // Second call at a NON-increasing timestamp t2 <= t1 must REVERT in P.
        // The mutant (guard deleted) accepts it and overwrites pastBlockTime.
        uint256 t2 = t1 - delta; // t2 <= t1, possibly far smaller
        vm.warp(t2);
        vm.deal(address(this), 10 ether);
        bool ok = true;
        // c.fallback{value: 10 ether}();  // not allowed as statement name in solidity <=0.8?
        (bool sent, ) = address(c).call{value: 10 ether}("");
        ok = sent;

        // General rule: for admissible inputs, P accepts the second call only if
        // t2 > pastBlockTime. Here t2 <= t1 < stored1, so the second call MUST revert.
        assertTrue(!ok || t2 > stored1, "second call must revert when timestamp not increasing");
    }
}

