pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNumber, address actor) public {
        blockNumber = bound(blockNumber, 15, type(uint256).max / 2);
        vm.assume(blockNumber % 15 == 0);
        vm.assume(actor != address(c) && actor != address(0));

        vm.roll(blockNumber);
        vm.warp(1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // Rule: a winning call drains the contract's ENTIRE balance.
        assertTrue(address(c).balance == 0);
    }
}

